<template>
    <aside class="filters-sidebar">
      <h2>Filtrer par</h2>
  
      <!-- Section : Catégorie -->
      <div class="filter-category">
        <h3>Catégorie</h3>
        <div 
          v-for="cat in categories" 
          :key="cat.name"
          class="checkbox-item"
        >
          <input
            type="checkbox"
            :id="cat.name"
            :value="cat.name"
            v-model="checkedCategories"
          />
          <label :for="cat.name">{{ cat.label }}</label>
        </div>
      </div>
  
      <!-- Section : Goût (exemple, non relié au filtrage) -->
      <div class="filter-category">
        <h3>Goût</h3>
        <div class="checkbox-item">
          <input type="checkbox" id="fume" value="Fumé" />
          <label for="fume">Fumé</label>
        </div>
        <div class="checkbox-item">
          <input type="checkbox" id="epice" value="Épicé" />
          <label for="epice">Épicé</label>
        </div>
      </div>
  
      <!-- Section : Viande (exemple) -->
      <div class="filter-category">
        <h3>Viande</h3>
        <div class="checkbox-item">
          <input type="checkbox" id="bœuf" value="Bœuf" />
          <label for="bœuf">Bœuf</label>
        </div>
        <div class="checkbox-item">
          <input type="checkbox" id="porc" value="Porc" />
          <label for="porc">Porc</label>
        </div>
      </div>
  
      <!-- Section : Label (exemple) -->
      <div class="filter-category">
        <h3>Label</h3>
        <div class="checkbox-item">
          <input type="checkbox" id="label-rouge" value="Label Rouge" />
          <label for="label-rouge">Label Rouge</label>
        </div>
        <div class="checkbox-item">
          <input type="checkbox" id="bio" value="Bio" />
          <label for="bio">Bio</label>
        </div>
      </div>
  
    </aside>
  </template>
  
  <script>
  export default {
    name: 'FiltersSidebar',
    props: {
      categories: {
        type: Array,
        default: () => []
      },
      // Pour la section "Catégorie" reliée au parent
      modelValue: {
        type: Array,
        default: () => []
      }
    },
    computed: {
      checkedCategories: {
        get() {
          return this.modelValue
        },
        set(value) {
          this.$emit('update:modelValue', value)
        }
      }
    }
  }
  </script>
  
  <style scoped>
  .filters-sidebar {
    width: 220px;
    background: #fff;
    padding: 1rem;
    border-radius: 8px;
    border: 1px solid #ddd;
  }
  
  .filters-sidebar h2 {
    color: #7f1a1a;
    margin-bottom: 1rem;
    font-size: 1.3rem;
  }
  
  .filter-category {
    margin-bottom: 1.5rem;
  }
  
  .filter-category h3 {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
    color: #333;
  }
  
  .checkbox-item {
    margin-bottom: 0.5rem;
  }
  
  .checkbox-item input {
    margin-right: 0.5rem;
    transform: translateY(1px);
  }
  
  .checkbox-item label {
    color: #555;
  }
  </style>
  