<template>
    <section class="commande-traiteur">
      <!-- Titre de la section -->
      <h1>Nos Fiches Traiteurs</h1>
      
      <!-- Grille de cartes -->
      <div class="cards-container">
        <div 
          class="card" 
          v-for="n in 12" 
          :key="n"
          @click="openModal"
        >
          <img src="@/assets/traiteur.jpg" alt="Fiche traiteur" />
        </div>
      </div>
    
      <!-- Modal pour afficher l'image agrandie -->
      <div v-if="modalOpen" class="modal-overlay" @click.self="closeModal">
        <div class="modal-content">
          <button class="close-btn" @click="closeModal">&times;</button>
          <img src="@/assets/traiteur.jpg" alt="Image agrandie" />
        </div>
      </div>
    </section>
  </template>
  
  <script>
  export default {
    name: 'CommandeTraiteur',
    data() {
      return {
        modalOpen: false
      }
    },
    methods: {
      openModal() {
        this.modalOpen = true;
      },
      closeModal() {
        this.modalOpen = false;
      }
    }
  }
  </script>
  
  <style scoped>
  .commande-traiteur {
    padding: 2rem;
    font-family: ui-sans-serif, system-ui, sans-serif;
    /* Suppression du background-color */
  }
  
  .commande-traiteur h1 {
    text-align: center;
    margin-bottom: 2rem;
    font-size: 2rem;
    color: #333;
  }
  
  /* Grille responsive avec 12 cartes */
  .cards-container {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1rem;
    max-width: 1200px;
    margin: 0 auto;
  }
  
  /* Carte individuelle */
  .card {
    background-color: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    /* Forcer la même hauteur pour chaque card */
    height: 200px;
  }
  
  .card:hover {
    transform: translateY(-5px);
    box-shadow: 0 8px 16px rgba(0,0,0,0.15);
  }
  
  .card img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
  }
  
  /* Modal styles */
  .modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0,0,0,0.7);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
  }
  
  .modal-content {
    position: relative;
    background: #fff;
    padding: 1rem;
    border-radius: 8px;
    max-width: 90%;
    max-height: 90%;
    overflow: auto;
  }
  
  .modal-content img {
    width: 100%;
    height: auto;
    display: block;
  }
  
  .close-btn {
    position: absolute;
    top: 0.5rem;
    right: 0.5rem;
    background: transparent;
    border: none;
    font-size: 2rem;
    line-height: 1;
    color: #333;
    cursor: pointer;
  }
  </style>
  