import { createRouter, createWebHashHistory } from 'vue-router';
import Home from '@/pages/Home.vue';
import Produits from '@/pages/Produits.vue';
import Traiteurs from '@/pages/Traiteurs.vue';
import Apropos from '@/pages/Apropos.vue';
import Contact from '@/pages/Contact.vue';
import Login from '@/pages/Login.vue';
import Signup from '@/pages/Signup.vue';
import Panier from '@/pages/Panier.vue';
import ProductDetail from '@/pages/ProductDetail.vue'

const routes = [
  { path: '/', component: Home },
  { path: '/produits', component: Produits },
  { path: '/traiteurs', component: Traiteurs },
  { path: '/a-propos', component: Apropos },
  { path: '/contact', component: Contact },
  { path: '/login', component: Login },
  { path: '/signup', component: Signup },
  { path: '/panier', component: Panier },
  {
    path: '/produits/:id',
    name: 'ProductDetail',
    component: ProductDetail,
    props: true // autorise le passage de :id en prop
  },
];

const router = createRouter({
  history: createWebHashHistory(), // 🔥 On passe en hash mode ici !
  routes,
});

export default router;
