<template>
    <div class="product-info">
      <p class="price">{{ product.price.toFixed(2) }} € TTC</p>
      <p class="short-description">{{ product.description }}</p>
      <div class="categories" v-if="product.categories && product.categories.length">
        <span v-for="(cat, index) in product.categories" :key="index">{{ cat }}</span>
      </div>
  
      <div class="selectors">
        <div class="weight">
          <label for="weightSelect">Poids</label>
          <select id="weightSelect" v-model="selectedWeight">
            <option v-for="option in weightOptions" :key="option" :value="option">
              {{ option }}
            </option>
          </select>
        </div>
  
        <div class="quantity">
          <label for="quantityInput">Quantité</label>
          <input id="quantityInput" type="number" min="1" v-model.number="quantity" />
        </div>
      </div>
  
      <button class="add-to-cart" @click="$emit('add-to-cart')">Ajouter au panier</button>
      <p class="shipping-info">
        Livraison en 24h (hors week-end) à domicile.
      </p>
    </div>
  </template>
  
  <script>
  export default {
    name: 'ProductInfo',
    props: {
      product: {
        type: Object,
        required: true
      },
      weightOptions: {
        type: Array,
        default: () => ['1kg', '2kg', '3kg']
      }
    },
    data() {
      return {
        selectedWeight: '1kg',
        quantity: 1
      }
    },
    watch: {
      // Vous pouvez émettre un événement pour informer le parent si nécessaire.
      selectedWeight(newVal) {
        this.$emit('update-weight', newVal)
      },
      quantity(newVal) {
        this.$emit('update-quantity', newVal)
      }
    }
  }
  </script>
  
  <style scoped>
  .product-info {
    display: flex;
    flex-direction: column;
    gap: 1rem;
  }
  .price {
    font-size: 1.3rem;
    color: #333;
    font-weight: 600;
  }
  .short-description {
    color: #555;
    line-height: 1.5;
  }
  .categories span {
    background: #eee;
    padding: 0.3rem 0.6rem;
    margin-right: 0.5rem;
    border-radius: 4px;
    font-size: 0.9rem;
    color: #444;
  }
  .selectors {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
  }
  .weight, .quantity {
    display: flex;
    flex-direction: column;
  }
  .weight label, .quantity label {
    font-weight: 600;
    margin-bottom: 0.3rem;
  }
  .weight select, .quantity input {
    padding: 0.5rem;
    border: 1px solid #ddd;
    border-radius: 4px;
    font-size: 1rem;
    width: 100px;
  }
  .add-to-cart {
    background-color: #7f1a1a;
    color: #fff;
    border: none;
    padding: 0.8rem 1.2rem;
    border-radius: 4px;
    cursor: pointer;
    width: fit-content;
  }
  .add-to-cart:hover {
    background-color: #691414;
  }
  .shipping-info {
    font-size: 0.9rem;
    color: #555;
  }
  </style>
  