<template>
    <section class="product-detail-page">
      <Header />
  
      <!-- Conteneur principal -->
      <div class="product-detail-container">
        <!-- Partie gauche : Image + Titre en grand -->
        <div class="product-left">
          <ProductHeader :product="product" :productImage="productImage" />
        </div>
  
        <!-- Partie droite : Infos, sélecteurs, etc. -->
        <div class="product-info-section">
          <ProductInfo 
            :product="product"
            :weightOptions="weightOptions"
            @add-to-cart="addToCart"
          />
        </div>
      </div>
  
      <!-- Section Suggestions -->
      <ProductSuggestions 
        :relatedProducts="relatedProducts" 
        @select-product="goToProduct"
      />
  
      <!-- Section Description Complète -->
      <ProductAdditionalInfo />
  
      <FooterBoucherie />
    </section>
  </template>
  
  <script>
  import Header from '@/components/Header.vue'
  import FooterBoucherie from '@/components/FooterBoucherie.vue'
  import ProductHeader from '@/components/produits-details/ProductHeader.vue'
  import ProductInfo from '@/components/produits-details/ProductInfo.vue'
  import ProductSuggestions from '@/components/produits-details/ProductSuggestions.vue'
  import ProductAdditionalInfo from '@/components/produits-details/ProductAdditionalInfo.vue'
  
  export default {
    name: 'ProductDetail',
    components: {
      Header,
      FooterBoucherie,
      ProductHeader,
      ProductInfo,
      ProductSuggestions,
      ProductAdditionalInfo
    },
    props: ['id'],
    data() {
      return {
        // Produit simulé (sera remplacé si trouvé dans allProducts)
        product: {
          id: 1,
          name: 'Lard gras salé',
          price: 12.50,
          description: 'Lard gras frais de porc légèrement fumé.',
          categories: ['Porc']
        },
        // Image principale du produit
        productImage: require('@/assets/test-produits.jpg'),
        // Liste simulée pour suggestions
        allProducts: [
          { id: 1, name: 'Lard gras salé', price: 12.50, categories: ['Porc'] },
          { id: 2, name: 'Planche découverte saucisson', price: 15.00, categories: ['Charcuterie'] },
          { id: 3, name: 'Lard entier fumé', price: 16.00, categories: ['Porc'] },
          { id: 4, name: 'Côte de bœuf', price: 28.00, categories: ['Bœuf'] },
          { id: 5, name: 'Saucisses de porc', price: 6.00, categories: ['Porc'] }
        ],
        weightOptions: ['1kg', '2kg', '3kg']
      }
    },
    computed: {
      relatedProducts() {
        if (!this.product.categories || this.product.categories.length === 0) {
          return []
        }
        const mainCat = this.product.categories[0]
        const sameCat = this.allProducts.filter(
          p => p.categories.includes(mainCat) && p.id !== this.product.id
        )
        return sameCat.slice(0, 3)
      }
    },
    methods: {
      addToCart() {
        alert(`Vous avez ajouté ${this.product.name} au panier.`)
      },
      goToProduct(id) {
        this.$router.push({ name: 'ProductDetail', params: { id } })
      }
    },
    mounted() {
      const numericId = parseInt(this.id, 10)
      const found = this.allProducts.find(p => p.id === numericId)
      if (found) {
        this.product = {
          ...found,
          description: 'Lard gras frais de porc légèrement fumé. (Description détaillée du produit.)'
        }
      }
    }
  }
  </script>
  
  <style scoped>
  /* La page commence juste en dessous de la navbar fixe grâce à ce padding-top */
  .product-detail-page {
    background-color: #f8f9fa;
    min-height: 100vh;
    padding: 80px 0rem 2rem 0rem;
    font-family: ui-sans-serif, system-ui, sans-serif;
  }
  
  /* Conteneur principal : image+infos */
  .product-detail-container {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    gap: 2rem;
    margin-bottom: 2rem;
  }
  
  .product-left {
    width: 50%;
  }
  .product-info-section {
    flex: 1;
  }
  
  /* On ajoute une marge supplémentaire en bas de la section de description complète pour éloigner le bouton de retour du footer */
  .product-additional-info {
    max-width: 1200px;
    margin: 2rem auto 4rem auto;
    padding: 0 1rem;
  }
  </style>
  