<template>
  <div>
    <Header />

    <section class="produits-page">
      <!-- Texte d’intro -->
      <ProductsIntro />

      <!-- Info : nombre de produits trouvés -->
      <div class="produits-info">
        <p>
          {{ totalFilteredProducts }} produit(s) trouvé(s)
        </p>
      </div>

      <!-- Conteneur principal : barre latérale + liste produits -->
      <div class="produits-main">
        <!-- Barre latérale -->
        <FiltersSidebar
          :categories="categories"
          v-model="selectedCategories"
        />
        <!-- Liste des produits (seulement ceux de la page courante) -->
        <ProductList :products="paginatedProducts" />
      </div>

      <!-- Pagination (en-dessous de la liste) -->
      <div class="pagination" v-if="totalPages > 1">
        <button 
          :disabled="currentPage === 1" 
          @click="prevPage"
        >
          Précédent
        </button>

        <span>Page {{ currentPage }} / {{ totalPages }}</span>

        <button 
          :disabled="currentPage === totalPages" 
          @click="nextPage"
        >
          Suivant
        </button>
      </div>
    </section>

    <FooterBoucherie />
  </div>
</template>

<script>
import Header from '@/components/Header.vue'
import FooterBoucherie from '@/components/FooterBoucherie.vue'
import ProductsIntro from '@/components/produits-components/ProductsIntro.vue'
import FiltersSidebar from '@/components/produits-components/FiltersSidebar.vue'
import ProductList from '@/components/produits-components/ProductList.vue'

export default {
  name: 'Produits',
  components: {
    Header,
    FooterBoucherie,
    ProductsIntro,
    FiltersSidebar,
    ProductList
  },
  data() {
    return {
      // Liste des catégories pour la sidebar
      categories: [
        { name: 'Bœuf', label: 'Bœuf' },
        { name: 'Porc', label: 'Porc' },
        { name: 'Charcuterie', label: 'Charcuterie' },
        { name: 'Volaille', label: 'Volaille' }
      ],
      // Les catégories cochées par l’utilisateur
      selectedCategories: [],

      // Données produits (exemple : 15 produits)
      products: [
        { id: 1, name: 'Côtes de porc',         categories: ['Porc'],         price: 8.90 },
        { id: 2, name: 'Colis de bœuf n°3',     categories: ['Bœuf'],         price: 17.90 },
        { id: 3, name: 'Saucisson Ardennais',   categories: ['Charcuterie'],  price: 5.50 },
        { id: 4, name: 'Poulet fermier',        categories: ['Volaille'],     price: 9.50 },
        { id: 5, name: 'Jambon sec',            categories: ['Charcuterie'],  price: 11.20 },
        { id: 6, name: 'Rôti de porc',          categories: ['Porc'],         price: 14.00 },
        { id: 7, name: 'Steak haché de bœuf',   categories: ['Bœuf'],         price: 4.90 },
        { id: 8, name: 'Filet de poulet',       categories: ['Volaille'],     price: 7.80 },
        { id: 9, name: 'Andouille ardennaise',  categories: ['Charcuterie'],  price: 6.50 },
        { id: 10, name: 'Travers de porc',      categories: ['Porc'],         price: 12.50 },
        { id: 11, name: 'Entrecôte de bœuf',    categories: ['Bœuf'],         price: 24.90 },
        { id: 12, name: 'Chipolatas',           categories: ['Charcuterie'],  price: 4.50 },
        { id: 13, name: 'Pintade fermière',     categories: ['Volaille'],     price: 10.90 },
        { id: 14, name: 'Côte de bœuf',         categories: ['Bœuf'],         price: 28.00 },
        { id: 15, name: 'Saucisses de porc',    categories: ['Porc'],         price: 6.00 }
      ],

      // Pagination
      currentPage: 1,
      maxPerPage: 12
    }
  },
  computed: {
    // 1) Produits filtrés en fonction des catégories cochées
    filteredProducts() {
      if (this.selectedCategories.length === 0) {
        return this.products
      } else {
        return this.products.filter(product =>
          product.categories.some(cat => this.selectedCategories.includes(cat))
        )
      }
    },
    // 2) Nombre total de produits filtrés
    totalFilteredProducts() {
      return this.filteredProducts.length
    },
    // 3) Nombre total de pages
    totalPages() {
      return Math.ceil(this.totalFilteredProducts / this.maxPerPage)
    },
    // 4) Produits à afficher sur la page courante
    paginatedProducts() {
      const startIndex = (this.currentPage - 1) * this.maxPerPage
      const endIndex = startIndex + this.maxPerPage
      return this.filteredProducts.slice(startIndex, endIndex)
    }
  },
  methods: {
    // Passer à la page précédente
    prevPage() {
      if (this.currentPage > 1) {
        this.currentPage--
      }
    },
    // Passer à la page suivante
    nextPage() {
      if (this.currentPage < this.totalPages) {
        this.currentPage++
      }
    }
  },
  watch: {
    // Quand les catégories sélectionnées changent, on remet la pagination à la page 1
    selectedCategories() {
      this.currentPage = 1
    }
  }
}
</script>

<style scoped>
.produits-page {
  max-width: 1200px;
  margin: 0 auto;
  background-color: #f8f9fa;
  min-height: 100vh;
  font-family: ui-sans-serif, system-ui, sans-serif;
  padding: 2rem;
}

/* Info sur le nombre de produits */
.produits-info {
  text-align: center;
  margin-top: 1rem;
}

/* Conteneur : sidebar + liste produits */
.produits-main {
  display: flex;
  gap: 1.5rem;
  margin-top: 2rem;
  justify-content: flex-end;
}

/* Pagination en bas */
.pagination {
  text-align: center;
  margin-top: 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
}

.pagination button {
  background-color: #7f1a1a;
  color: #fff;
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.pagination button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
</style>
