<template>
    <div class="product-list">
      <!-- Pour chaque produit, on rend la carte cliquable avec @click -->
      <div
        class="product-card"
        v-for="product in products"
        :key="product.id"
        @click="goToProduct(product.id)"
      >
        <!-- On utilise l'image test-produits.jpg -->
        <img 
          src="@/assets/test-produits.jpg" 
          alt="Produit"
          class="product-image"
        />
        <h3>{{ product.name }}</h3>
        <p class="price">{{ product.price.toFixed(2) }} €</p>
      </div>
    </div>
  </template>
  
  <script>
  export default {
    name: 'ProductList',
    props: {
      products: {
        type: Array,
        default: () => []
      }
    },
    methods: {
      goToProduct(id) {
        // Redirige vers la page de détail
        // Assurez-vous d’avoir défini une route { name: 'ProductDetail', params: { id } }
        this.$router.push({ name: 'ProductDetail', params: { id } })
      }
    }
  }
  </script>
  
  <style scoped>
  .product-list {
    display: grid;
    gap: 1rem;
    flex: 1;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  }
  
  /* Carte de produit */
  .product-card {
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    height: 320px; /* Hauteur fixe (ou min-height) pour uniformiser la taille */
    padding: 1rem;
    text-align: center;
    box-shadow: 0px 4px 8px rgba(0,0,0,0.1);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    cursor: pointer; /* Indique que la carte est cliquable */
  }
  
  .product-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 8px 16px rgba(0,0,0,0.15);
  }
  
  .product-image {
    width: 100%;
    height: 150px;
    object-fit: cover;
    margin-bottom: 0.5rem;
    border-radius: 4px;
  }
  
  .product-card h3 {
    color: #7f1a1a;
    margin-bottom: 0.5rem;
    font-size: 1.1rem;
  }
  
  .price {
    color: #333;
    font-size: 1rem;
  }
  </style>
  